# Lesson 1 of MKTG90037: what value is and who decides (Week 1). Brand: Who Gives a Crap (verified facts in brands.md);
# Coles for the sources of value. Instruments: persona value dial (Dial), means-end ladder (Place), sources of value (Place).
# The worked Apply here is complete; later lessons fade it.
from mk import *  # noqa: F403


def L01(CID):
    SK = 'mk.value'
    ladder_zones = [dict(id='att', label=T('Attributes: what the product is', '属性：产品是什么')), dict(id='fun', label=T('Functional consequence: what it does for me', '功能结果：它为我做了什么')),
                    dict(id='psy', label=T('Psychosocial consequence: how I feel, how others see me', '心理社会结果：我的感受、别人怎么看我')), dict(id='val', label=T('Value: what I am ultimately after', '价值观：我最终想要的'))]
    ladder_chips = [
        dict(id='a1', label=T('Rolls wrapped one by one in paper', '每一卷都用纸单独包好'), zone='att', why=T('A thing you can point at on the box.', '你能在包装上指出来的东西。')),
        dict(id='a2', label=T('50% of profits donated', '50% 的利润捐出'), zone='att', why=T('A fact about the offer itself, not yet what it means to the buyer.', '关于这个产品本身的事实，还没说它对买家意味着什么。')),
        dict(id='f1', label=T('A bulk box arrives at my door', '一大箱直接送到家门口'), zone='fun', why=T('The product does a job: I do not carry rolls home.', '产品替我做了一件事：不用自己把卷纸扛回家。')),
        dict(id='f2', label=T('No plastic wrap to throw away', '没有塑料包装要扔'), zone='fun', why=T('A concrete result of using it.', '使用它带来的具体结果。')),
        dict(id='p1', label=T('I feel I am helping, not just buying', '我觉得自己在帮忙，不只是买东西'), zone='psy', why=T('A feeling the attribute produces in the buyer.', '属性在买家心里引发的感受。')),
        dict(id='p2', label=T('Guests notice the brand and see what I care about', '客人会注意到这个牌子，看出我在乎什么'), zone='psy', why=T('A social consequence: how others read me.', '一种社会结果：别人怎么读我。')),
        dict(id='v1', label=T('Self-respect', '自尊'), zone='val', why=T('One of the terminal values on the Rokeach list.', 'Rokeach 价值观清单里的终极价值之一。')),
        dict(id='v2', label=T('Equality', '平等'), zone='val', why=T('Another terminal value: here, that everyone should have a toilet.', '另一个终极价值：这里指人人都该有厕所。')),
    ]
    src_zones = [dict(id='prod', label=T('Product', '产品')), dict(id='info', label=T('Information', '信息')), dict(id='env', label=T('Environment', '环境')),
                 dict(id='int', label=T('Interactions', '互动')), dict(id='own', label=T('Ownership', '所有权转移'))]
    src_chips = [
        dict(id='s1', label=T('The Coles Finest range', 'Coles Finest 系列'), zone='prod', why=T('The offer itself, including its brand and range.', '产品本身，包括品牌和系列。')),
        dict(id='s2', label=T('Flybuys points', 'Flybuys 积分'), zone='prod', why=T('Loyalty programmes belong to the augmented product.', '积分计划属于“扩展产品”。')),
        dict(id='s3', label=T('The price ticket on the shelf', '货架上的价签'), zone='info', why=T('Pricing is how the shopper is told what to expect.', '价格是告诉购物者该期待什么的信息。')),
        dict(id='s4', label=T('A television advertisement', '一条电视广告'), zone='info', why=T('Marketing communication shapes perceived value before the purchase.', '营销沟通在购买前就塑造感知价值。')),
        dict(id='s5', label=T('Store layout, lighting and the car park', '门店布局、灯光和停车场'), zone='env', why=T('The setting in which the purchase happens.', '购买发生的场景。')),
        dict(id='s6', label=T('How the online shop is laid out', '线上商店的版面设计'), zone='env', why=T('The online setting is an environment too.', '线上场景同样是一种环境。')),
        dict(id='s7', label=T('The team member who helps at the self-checkout', '在自助结账旁帮忙的员工'), zone='int', why=T('A person-to-customer interaction.', '人与顾客的互动。')),
        dict(id='s8', label=T('Online chat help', '线上聊天客服'), zone='int', why=T('A system interaction.', '一种系统互动。')),
        dict(id='s9', label=T('A refund policy', '退款政策'), zone='own', why=T('Ownership is about the transfer: payment, warranty, returns.', '所有权关乎转移过程：付款、保修、退货。')),
        dict(id='s10', label=T('Choice of payment methods', '可选的付款方式'), zone='own', why=T('How the shopper pays is part of the transfer.', '怎么付款也是转移的一部分。')),
    ]
    return dict(
        id=f'{CID}-value',
        title=T('Why the same product is worth different amounts to different people', '同一个产品，为什么对不同的人价值不同'),
        description=T('Start from one purchase two people make for opposite reasons, then learn what value is, the four types, and where firms create them, using Who Gives a Crap and Coles.',
                      '从两个人为相反的理由做出的同一次购买出发，弄清价值是什么、有哪四种、企业从哪里创造它，案例是 Who Gives a Crap 和 Coles。'),
        minutes=45,
        skills=[{'id': SK, 'name': T('Explaining and applying customer value', '解释并应用顾客价值')}],
        misconceptions=[
            {'id': 'value-is-price', 'description': T('value just means a low price', '价值就是低价')},
            {'id': 'value-in-product', 'description': T('value sits in the product, the same for every buyer', '价值就在产品里，对每个买家都一样')},
            {'id': 'only-benefits', 'description': T('value is about benefits only, and costs other than price do not matter', '价值只看收益，价格之外的成本不重要')},
        ],
        steps=[
            read('puzzle', T('Two shoppers, one aisle', '同一条货架，两个顾客'),
                 p(T("Two people walk down the toilet-paper aisle, or open the same website. One pays more for **Who Gives a Crap**, a company that says it donates 50% of its profits to water and sanitation projects. The other buys the cheapest pack on the shelf. Both are sure they chose well.",
                     "两个人走过卷纸货架，或者打开同一个网站。一个多花钱买 **Who Gives a Crap**，这家公司说自己把 50% 的利润捐给供水和卫生项目。另一个买货架上最便宜的那包。两个人都确信自己选对了。")),
                 p(T("If a product had one fixed value, one of them is wrong. So either someone is irrational, or **value is not where we thought it was**.", "如果一个产品只有一个固定的价值，那就有一个人选错了。要么有人不理性，要么**价值根本不在我们以为的地方**。")),
                 chapter=CH['puzzle']),
            predict('guess', SK, T("Whose purchase is the rational one?", "谁的购买是理性的？"),
                    [(T("The one who pays more: the better product is worth more", "多花钱的那个：更好的产品值更多钱"), T("“Better” for whom? A buyer who only needs a roll that works gets nothing extra from the donation.", "“更好”是对谁而言？只需要一卷能用的纸的买家，并不会因为捐赠多得到什么。")),
                     (T("The one who pays less: toilet paper is a commodity", "花得少的那个：卷纸就是大路货"), T("For this buyer, yes; but you cannot say it for everyone. Some people want something the cheap roll does not give.", "对这个买家来说是；但不能对所有人这么说。有些人想要便宜卷纸给不了的东西。")),
                     (T("Both: each gets what they value", "两个都是：各得其所"), True),
                     (T("Neither: a rational buyer would not care", "都不是：理性的买家根本不在乎"), T("That assumes only price counts. Buyers value other things, and that is the point of the lesson.", "这是假设只有价格重要。买家还看重别的东西，这正是这节课的重点。"))],
                    T("Both. Value is **in the buyer’s head**: it is what *this* customer perceives they get compared with what they give up and with the alternatives. Now you will set a customer’s priorities yourself.",
                      "两个都是。价值**在买家的脑子里**：是*这个*顾客觉得自己得到的，对比他付出的，再对比其他选择。现在你来亲手调一个顾客的优先级。")),
            read('touch', T('Change the shopper, change the winner', '换一个顾客，赢家就变了'),
                 p(T("The dial gives a shopper four priorities. Two rolls are scored on four things. Drag the priorities, or press a ready-made shopper, and watch which roll wins.", "下面的转盘给一个购物者四种优先级。两种卷纸在四个方面各有得分。拖动优先级，或者点一个现成的购物者，看哪一种卷纸赢。")),
                 dial(T('A shopper with four priorities (practical, enjoyable, expresses me, low cost) and two rolls, a purpose-led one and a budget one; the scores show which one wins for that shopper.',
                        '一个有四种优先级（实用、享受、表达自我、低成本）的购物者，和两种卷纸：公益型和平价型；得分显示对这位购物者哪一种赢。'),
                      sliders=[dict(id='wf', label=T('Does the job', '好用'), min=0, max=10, step=1, value=5), dict(id='we', label=T('Is a nice thing to use', '用着舒服、有意思'), min=0, max=10, step=1, value=3),
                               dict(id='ws', label=T('Says something about me', '能表达我是谁'), min=0, max=10, step=1, value=2), dict(id='wc', label=T('Costs me little', '花得少'), min=0, max=10, step=1, value=8)],
                      consts=dict(pf=6, pe=6, ps=9, pc=3, bf=6, be=3, bs=2, bc=9),
                      outs=[dict(id='tot', label=T('weight in total', '权重合计'), expr='wf+we+ws+wc+0.0001', dec=0, hide=True),
                            dict(id='purpose', label=T('Purpose-led roll', '公益型卷纸'), expr='(wf*pf+we*pe+ws*ps+wc*pc)/tot', dec=1, bar=dict(max=10)),
                            dict(id='budget', label=T('Budget roll', '平价卷纸'), expr='(wf*bf+we*be+ws*bs+wc*bc)/tot', dec=1, bar=dict(max=10))],
                      presets=[dict(label=T('Student on a tight budget', '预算很紧的学生'), set=dict(wf=5, we=2, ws=1, wc=10)), dict(label=T('Household that cares about the cause', '在乎这件事的家庭'), set=dict(wf=5, we=4, ws=9, wc=3)),
                               dict(label=T('Café owner buying for guests', '给客人买纸的咖啡馆老板'), set=dict(wf=6, we=8, ws=7, wc=4))],
                      notes=[dict(when='purpose>budget', text=T('**The purpose-led roll wins** for this shopper: what it gives (meaning, a nicer thing to use) outweighs what it costs.', '对这位购物者，**公益型卷纸赢**：它给的东西（意义、更舒服）压过了它的成本。')),
                             dict(when='budget>purpose', text=T('**The budget roll wins** for this shopper: low cost is the priority and the extras do not move them.', '对这位购物者，**平价卷纸赢**：低成本是第一位，额外的东西打动不了他。')),
                             dict(when='Math.abs(budget-purpose)<0.05', text=T('A tie: this shopper would hesitate. Move one priority.', '打平：这个购物者会犹豫。动一个优先级试试。'))],
                      caption=T("The levels of the two rolls are made up for this lesson to show the mechanism; they are not measurements of any brand.", "两种卷纸的得分是为演示机制而设的，不是任何品牌的测量值。"), height=640),
                 chapter=CH['touch']),
            read('touch2', T('Why the buyer wants it: a ladder', '买家为什么想要它：一把梯子'),
                 p(T("People do not want attributes. They want what the attribute leads to, and what *that* leads to, up to something they value in life. Build the ladder for Who Gives a Crap (this is the course’s reading of the brand, not a company statement).",
                     "人们要的不是属性，而是属性带来的结果，以及这个结果又带来什么，一路往上，直到生活里看重的东西。为 Who Gives a Crap 搭这把梯子（这是本课程对品牌的解读，不是公司说法）。")),
                 place(T('Eight cards to place on a four-step ladder: attributes, functional consequences, psychosocial consequences, values.', '八张卡片，放到四级梯子上：属性、功能结果、心理社会结果、价值观。'),
                       ladder_zones, ladder_chips, cols=1,
                       done=T("The **means-end chain**: attribute → functional consequence → psychosocial consequence → value. A buyer who tops out at “it works” never reaches the top rungs; a firm that sells only to the bottom rung competes on price.",
                              "这就是**手段–目的链**：属性 → 功能结果 → 心理社会结果 → 价值观。只停在“好用”这一级的买家到不了高处；只卖到最低一级的企业，只能比价格。"),
                       height=760)),
            read('touch3', T('Where firms create value', '企业从哪里创造价值'),
                 p(T("A product does not arrive with value attached. The firm builds it from five places. Sort what Coles does into them.", "产品出厂时不会自带价值。企业从五个地方把它造出来。把 Coles 的做法分到这五处。")),
                 place(T('Ten things Coles does, to place under five sources of value: product, information, environment, interactions, ownership.', 'Coles 的十件事，分到五个价值来源下：产品、信息、环境、互动、所有权转移。'),
                       src_zones, src_chips, cols=3,
                       done=T("Five sources, in the order the customer meets them. A weak spot in any one can spoil the value in the others: a great product behind a slow checkout still feels poor value.",
                              "五个来源，正是顾客依次遇到的顺序。任何一处薄弱，都会拖累其余：产品再好，结账慢，也会觉得不值。"),
                       height=900)),
            read('name', T('The framework, as the marker wants it', '阅卷人要的框架'),
                 p(T("Customers are the point of a firm. “The purpose of a business is to create and keep customers” (Drucker), and “the customer rarely buys what the firm thinks it is selling”. Value is therefore **perceived** (it lives in the customer’s mind), **relative** (to this customer and to the alternatives) and **dynamic** (it changes with time and situation).",
                     "顾客是企业存在的理由。“企业的目的是创造并留住顾客”（Drucker），“顾客很少买企业以为自己在卖的东西”。所以价值是**感知的**（存在于顾客心里）、**相对的**（相对这个顾客和其他选择）、**动态的**（随时间和情境变化）。")),
                 h(T('Four ordinary meanings of “value” (Zeithaml)', '“价值”的四种日常含义（Zeithaml）')),
                 table([T('Customers say', '顾客会说'), T('Which means', '意思是')],
                       [T('“Value is a low price”', '“价值就是低价”'), T('only what is given up counts (fast fashion: “I feel bad for the environment, but I am broke”)', '只算付出了什么（快时尚：“我对环境有愧，但我真没钱”）')],
                       [T('“Value is what I want in a product”', '“价值就是我想要产品里有的东西”'), T('benefits matter, not the price: the means-end chain above', '看重收益而非价格：就是上面的手段–目的链')],
                       [T('“Value is the quality I get for the price”', '“价值就是花这个价钱得到的质量”'), T('benefits divided by price (or benefits minus price)', '收益除以价格（或收益减价格）')],
                       [T('“Value is what I get for what I give”', '“价值就是我付出多少、得到多少”'), T('all the gets against all the gives, including time, effort and risk', '所有的得到对照所有的付出，包括时间、精力和风险')]),
                 h(T('Consumers and businesses mean different things', '消费者和企业买家的“价值”不一样')),
                 table([T('Aspect', '方面'), T('Consumer (B2C)', '消费者（B2C）'), T('Business buyer (B2B)', '企业买家（B2B）')],
                       [T('Benefits are', '收益是'), T('individual, subjective, unique to the person (a handbag can cost thousands or about sixty dollars and both be good value)', '个人的、主观的、因人而异（一个手提包可以几千元，也可以六十元左右，各有各的道理）'), T('objective and general, judged on return on investment', '客观的、普遍的，按投资回报来评判')],
                       [T('Value is described by', '价值描述为'), T('what I want, and how I feel', '我想要什么、我什么感觉'), T('results delivered: better performance, better productivity, better use of assets, less risk', '交付的结果：更好的表现、更高的效率、资产更好用、风险更低')],
                       [T('Costs are', '成本是'), T('money, time, effort and mental strain', '钱、时间、精力和心理负担'), T('total costs over the relationship, not just the invoice', '整个合作期的总成本，不只是发票金额')]),
                 callout('note', T('Price is the weakest way to stand out', '价格是最弱的差异化手段'), T("Research on industrial buyers (Ulaga and Eggert) found that **cost competitiveness is necessary but not sufficient**: a supplier must be competitive on price to be considered, but only superior benefits win a bigger share of the customer’s business. Price has the **weakest potential for differentiation**.",
                                                                                                     "对工业品买家的研究（Ulaga 和 Eggert）发现：**成本有竞争力是必要条件，但不充分**：供应商价格要有竞争力才会被考虑，但只有更好的收益才能赢得更大份额。价格的**差异化潜力最弱**。")),
                 h(T('Four types of value', '四类价值')),
                 table([T('Type', '类型'), T('The customer gets', '顾客得到'), T('In the WGAC example', '放到 Who Gives a Crap 上')],
                       [T('Functional', '功能价值'), T('features and performance that do the job', '把事办成的功能与性能'), T('a roll that works, delivered in bulk', '一卷好用的纸，批量送到家')],
                       [T('Experiential', '体验价值'), T('sensory, emotional, social and intellectual experience', '感官、情感、社交与认知上的体验'), T('paper-wrapped rolls; the pleasure of using them', '纸包装的卷纸；用起来的愉悦')],
                       [T('Symbolic', '象征价值'), T('what it means: identity, self-worth, social meaning', '它的意义：身份、自我价值、社会含义'), T('“I am the kind of person who funds toilets”', '“我是会出钱修厕所的那种人”')],
                       [T('Cost', '成本价值'), T('less sacrificed: lower price, but also less effort, time and risk (returns policy)', '付出更少：价格更低，也包括更少的精力、时间和风险（退货政策）'), T('a higher price, offset by fewer shopping trips', '价格更高，但少跑几趟店')]),
                 p(T("Which type matters most **depends on who the customer is**: a lawyer may buy a pen for symbol, a nurse for function, a shop assistant for cost. And remember the three directions of value: to the customer, to the firm, and to other stakeholders such as government and the environment. Managers often have to **trade these off**.",
                     "哪一类最重要，**取决于顾客是谁**：律师买笔可能为象征，护士为功能，店员为价格。还要记住价值的三个方向：对顾客、对企业、对政府和环境等其他利益相关者。管理者常常要在它们之间**做取舍**。")),
                 chapter=CH['name']),
            read('worked', T('Worked: Who Gives a Crap, step by step', '示范：一步步分析 Who Gives a Crap'),
                 p(T("Here is a complete Apply, with the job of each sentence in brackets. Read it as a pattern: later lessons ask you to write more of it yourself.", "下面是一份完整的“应用”，括号里标出每句话的作用。把它读成一个模式：后面的课会要求你自己写得越来越多。")),
                 callout('note', T('The method in four moves', '四步方法'), T("1. **Pick the customer**: value is relative, so say whose. 2. **Pick the types** that matter to *that* customer. 3. For each, **one fact about the company**. 4. **Because**: say how the fact creates that value (and what it costs the customer).",
                                                                                 "1. **选顾客**：价值是相对的，先说是谁的。2. 选出对*这位*顾客重要的**价值类型**。3. 每种配**一条公司事实**。4. **因为**：说清这条事实怎样创造这种价值（以及顾客为此付出什么）。")),
                 paper(T('Model Apply (about 230 words)', '范文“应用”部分（约 230 词）'),
                       T("[idea] For an environmentally and socially minded household, Who Gives a Crap creates mainly symbolic and functional value, and asks for a higher cost value in return. [fact] The company says it donates 50% of its profits to water and sanitation projects and is a certified B Corp. [because] This gives the buyer symbolic value: each purchase becomes evidence of the buyer’s own values, and the visible, certified giving makes the claim believable to guests and to the buyer. [fact] The rolls are made from recycled or bamboo paper, each wrapped in paper, and delivered in bulk to the door. [because] That adds functional value, because the household does not carry packs home or throw away plastic, and a little experiential value, because the product feels different to use. [cost] The shopper gives up more: it is priced at or above budget supermarket brands (the company does not compete on the lowest price), and the order has to be placed online and in advance. [because] So the value is positive only for shoppers whose symbolic gain outweighs this extra sacrifice, which is why a price-driven shopper rationally buys the cheapest pack.",
                         "[概念] 对一个关心环境与社会的家庭，Who Gives a Crap 创造的主要是象征价值和功能价值，并要求顾客在成本上付出更多。[事实] 公司称把 50% 的利润捐给供水和卫生项目，并且是认证的 B Corp。[因为] 这给了买家象征价值：每次购买都成为买家自己价值观的证据，而可见、经认证的捐赠让这个说法对客人和买家本人都可信。[事实] 卷纸用再生纸或竹子制成，每卷单独用纸包装，并大批量送货上门。[因为] 这增加了功能价值，因为家庭不用把纸扛回家，也没有塑料垃圾；还带来少量体验价值，因为用起来感觉不同。[成本] 购物者付出更多：它的定价不低于平价超市品牌（公司不靠最低价竞争），而且要提前在线下单。[因为] 所以只有象征收益超过这额外付出的顾客，价值才为正；这也是为什么看重价格的顾客理性地买最便宜的那包。"),
                       answer=True),
                 p(T("Notice what it does **not** do: it never defines value again, and it never says “Who Gives a Crap creates value” without a fact and a because.", "注意它**没有**做的事：没有再定义一遍价值，也没有不加事实和“因为”就说“Who Gives a Crap 创造价值”。"))),
            apply_q('apply', SK, T("Your turn, with a little scaffolding. Pick **one Coles shopper** (say who) and **one value type**. Write three sentences: the type and the shopper, one fact about Coles, and the *because*.", "轮到你了，给一点支架。选**一类 Coles 的购物者**（说清是谁）和**一种价值类型**。写三句话：类型和购物者；一条 Coles 的事实；以及“因为”。"),
                    [T("Names a specific shopper (value is relative to the customer)", "点明具体的购物者（价值相对于顾客）"),
                     T("Names one type of value correctly (functional, experiential, symbolic or cost)", "正确点出一种价值类型"),
                     T("Gives a true fact about Coles, for example online sales growth, Own Brand ranges, Flybuys or cost savings used to fund value", "给出一条关于 Coles 的真实事实，如线上销售增长、自有品牌、Flybuys、用成本节省投入价格"),
                     T("Explains cause and effect: how the fact creates that value for that shopper", "讲清因果：这条事实怎样为这位购物者创造这种价值")],
                    T("For a time-poor working parent, Coles creates mostly cost value in the form of saved effort and time, not only price. Coles grew online sales by 26.4% in FY26 and offers same-day delivery from its own fulfilment centres, so the parent can avoid a trip and the effort of carrying a shop home. That is value because the sacrifice they care about is time, and the delivery reduces it.",
                      "对一位没时间的上班家长，Coles 创造的主要是成本价值，表现为省下的精力和时间，而不只是价格。Coles 在 2026 财年线上销售增长 26.4%，并用自有履约中心提供当日送达，所以家长不用跑一趟，也不用把整周的货扛回家。这构成价值，是因为他们在意的付出是时间，而送货降低了它。"),
                    T("A good answer picks the sacrifice the shopper feels and shows the fact reducing it.", "好答案抓住购物者感到的那种付出，并说明事实怎样减少了它。")),
            choice('neighbour', T('Value to whom?', '谁的价值？'), SK,
                   T("Coles reports record profit. A student writes: “So Coles creates a lot of customer value.” What is wrong?", "Coles 报告创纪录的利润。一个学生写道：“所以 Coles 创造了大量顾客价值。”问题在哪？"),
                   [(T("Profit is value to the firm; value to the customer is a separate thing that has to be shown", "利润是企业的价值；顾客价值是另一回事，需要另外论证"), True),
                    (T("Nothing: profit proves customers value the firm", "没问题：利润证明顾客看重这家企业"), T("Profit can come from a lack of alternatives, high prices or cost cutting. It shows firm value, not what the customer perceives.", "利润可能来自没有替代品、价格高或削减成本。它说明的是企业价值，不是顾客感知的价值。")),
                    (T("Coles should have used the word “customer-centric”", "应该用“以顾客为中心”这个词"), T("Wording is not the problem; the claim has no evidence on the customer side.", "措辞不是问题；问题是顾客一侧没有证据。"))],
                   T("Keep the three directions apart: value to the customer, to the firm, to other stakeholders. In week 9 you will measure the firm’s side; here the question is what the customer perceives.", "分清三个方向：对顾客、对企业、对其他利益相关者。第 9 周你会衡量企业一侧；这里的问题是顾客感知到什么。"),
                   purpose='check', chapter=CH['neighbour']),
            recall('r1', SK, T("From lesson 0: in the exam, how many recommendations should the Recommend part give?", "来自第 0 课：考试里“建议”部分该给几条建议？"),
                   [(T("Exactly two", "恰好两条"), True), (T("As many as possible", "越多越好"), T("The paper says ONLY 2.", "考卷写的是只给 2 条。")), (T("One, to be safe", "一条，稳妥"), T("Two are asked for.", "要求的是两条。"))],
                   T("Two, each following from your analysis.", "两条，各自从你的分析里推出。"), first=True),
            recall('r2', SK, T("From lesson 0: which of these sentences earns marks in an Apply part?", "来自第 0 课：下面哪句话在“应用”部分能拿分？"),
                   [(T("“Because Hilton franchises most hotels, it earns fees while owners carry the building costs.”", "“因为 Hilton 的多数酒店是特许经营，所以它收费，建筑成本由业主承担。”"), True),
                    (T("“Hilton is a well-known global company.”", "“Hilton 是一家知名的全球公司。”"), T("True of any answer: filler.", "对任何答案都成立：废话。")),
                    (T("“Value is important to customers.”", "“价值对顾客很重要。”"), T("A sentence with no company in it.", "一句话里没有公司。"))],
                   T("Fact plus because: that is the pattern.", "事实加“因为”：就是这个模式。")),
        ] + exam_three('exam', SK,
                       T("Question. Customers judge value in different ways. (a) Explain the four types of customer value. (b) Using Who Gives a Crap in Australia, show how it creates and charges for these types of value. (c) Make two recommendations to its managers.",
                         "题目。顾客评判价值的方式不同。(a) 解释顾客价值的四种类型。(b) 以澳大利亚的 Who Gives a Crap 为例，说明它如何创造并为这些价值收费。(c) 给它的管理者两条建议。"),
                       (T("Write the **Explain** part (about 150 words).", "写**解释**部分（约 150 词）。"),
                        [T("Value is perceived by the customer and relative to the customer and the alternatives", "价值由顾客感知，相对于顾客和替代品"),
                         T("Names the four types: functional, experiential, symbolic, cost or sacrifice", "说出四种类型：功能、体验、象征、成本/付出"),
                         T("Says what each one means in a phrase (outcomes, feelings, meaning, lower sacrifice including time and risk)", "各用一句话说明含义（结果、感受、意义、更少付出含时间和风险）"),
                         T("Says that the importance of each depends on who the customer is", "说明每种的重要性取决于顾客是谁")],
                        T("Customer value is what a customer perceives they get compared with what they give up and with alternatives, so it is perceived, relative and dynamic. It has four types. Functional value is the performance and outcomes that do the job. Experiential value is the sensory, emotional or social experience. Symbolic value is the meaning the product carries, such as identity or self-worth. Cost value is lower sacrifice: not only price but also effort, time and risk. Which type matters most depends on the customer, so a firm has to build the sources of value that matter to its target segment rather than assume one value for all.",
                          "顾客价值是顾客觉得自己得到的，相对于付出的和其他选择，所以它是感知的、相对的、动态的。有四种类型。功能价值是把事办成的性能与结果。体验价值是感官、情感或社交体验。象征价值是产品承载的意义，如身份或自我价值。成本价值是更少的付出：不只是价格，也包括精力、时间和风险。哪一类最重要取决于顾客，所以企业要建设对目标客群重要的价值来源，而不是假定所有人价值相同。")),
                       (T("Write the **Apply** part (about 330 words). Use the method: customer, types, fact, because.", "写**应用**部分（约 330 词）。用这个方法：顾客、类型、事实、因为。"),
                        [T("Names a target customer for Who Gives a Crap", "指明 Who Gives a Crap 的目标顾客"),
                         T("Covers at least three of the four types with the company’s own facts: 50% of profits donated, B Corp, recycled or bamboo paper, paper-wrapped rolls, direct delivery", "至少用公司自己的事实覆盖四类中的三类：50% 利润捐赠、B Corp、再生纸或竹子、纸包装、直送"),
                         T("Explains cause and effect for each (how the fact creates that value for that buyer)", "为每一类讲清因果（这条事实怎样为该买家创造这种价值）"),
                         T("Analyses what the customer gives up (higher price, ordering ahead) and who it therefore fails", "分析顾客的付出（更高的价格、提前下单），以及它因此对谁不成立")],
                        T("(Use the worked Apply in this lesson as the pattern.) The target customer is a household that wants its everyday purchases to reflect its values. Symbolic value comes from the 50% profit pledge and B Corp certification: each purchase signals the buyer’s values and the certification makes the claim credible. Functional value comes from recycled or bamboo paper and bulk delivery to the door, which saves trips. Experiential value comes from paper-wrapped rolls that feel different to use. On cost, the buyer gives up more than at a supermarket: the price is at or above budget brands and the order is placed online in advance. So the offer creates positive value only where symbolic and convenience gains exceed that extra sacrifice, which explains why a price-driven shopper rationally buys the cheapest pack. This also shows the company is not competing on cost value.",
                          "（以本课“示范”为模板。）目标顾客是希望日常消费体现自己价值观的家庭。象征价值来自 50% 利润承诺和 B Corp 认证：每次购买都在表达买家的价值观，认证让这个说法可信。功能价值来自再生纸或竹子，以及批量送货上门，省了跑店。体验价值来自纸包装、用起来不一样的卷纸。成本方面，买家比在超市付出更多：价格不低于平价品牌，而且要提前在线下单。所以只有象征与便利的收益超过这份额外付出时，这个产品才创造正价值，这也解释了为什么看重价格的顾客理性地买最便宜的。这也说明公司并不在成本价值上竞争。")),
                       (T("Write the **Recommend** part: exactly two recommendations, each with how and a risk.", "写**建议**部分：恰好两条，每条写怎么做和一个风险。"),
                        [T("Exactly two recommendations", "恰好两条建议"),
                         T("Each follows from the analysis (for example reduce the cost sacrifice for new buyers, or make symbolic value visible)", "每条都从分析里推出（例如降低新买家的成本付出，或让象征价值看得见）"),
                         T("Each is actionable: says how it would be done", "每条可执行：说明怎么做"),
                         T("Names a risk or constraint, such as the profit pledge limiting discounts or claims needing proof", "点出风险或限制，如利润承诺限制折扣、说法需要证据")],
                        T("First, show each buyer what their own order funded, for instance on the receipt and the delivery box. This strengthens symbolic value for the segment that already cares and makes a higher price easier to justify; the risk is that every figure must be accurate and verifiable or it damages the trust the brand relies on. Second, offer a small first order for new buyers so the cost sacrifice of buying a bulk box online is lower at the moment of trial. This targets the segment that fails the value test on cost; the risk is margin, since half of profit is pledged, so the trial offer must be limited to first orders.",
                          "第一，让每位买家看到自己这一单资助了什么，比如印在小票和送货箱上。这会强化已经在乎这件事的客群的象征价值，也让较高价格更容易被接受；风险是每个数字必须准确可核实，否则会损害品牌赖以生存的信任。第二，为新买家提供小额首单，降低在线买一大箱的成本付出，便于试用。这瞄准的是在成本上通不过价值检验的客群；风险是利润率，因为一半利润已承诺，所以试用优惠只能限于首单。")),
                       ),
    )
